<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import MusicPlayer from './components/MusicPlayer.vue';
const config=ref({roles:[],avatars:[]}),room=ref(null),mode=ref('solo'),name=ref(''),role=ref('yu'),appearance=ref('yu-1'),code=ref(new URLSearchParams(location.search).get('room')||''),error=ref(''),notice=ref(''),busy=ref(false),waiting=ref(null),tab=ref('scene'),selected=ref(null),target=ref(''),text=ref(''),replyTo=ref(''),voteTarget=ref(''),voteClues=ref([]),scene=ref('account'),hint=ref(true),detail=ref(false),observation=ref(''),clock=ref(Date.now()),online=ref(true);
let session={};try{session=JSON.parse(localStorage.getItem('echo.formal.session')||'{}')}catch{}
let poll,clockTimer,destroyed=false,lastRequest=null;
const names=['候场','私密读本','查现场','搜证对质','私密指认','案件复盘'];
const goals=['选角并准备，邀请同伴加入。','读完四件事，然后确认已读。','找到现场证物，引用它向同伴提问。','调查账房，核对人物说法与证物。','选择另一名角色，写下你依据的证物。','看看你的证物究竟证明了什么。'];
const me=computed(()=>room.value?.players.find(p=>p.id===room.value.me));
const remaining=computed(()=>{if(!room.value)return '';const t=Math.max(0,Math.min([0,120,180,420,240,0][room.value.phase],Math.ceil((room.value.phaseDeadline-(clock.value+(room.value.serverTime-room.value.receivedAt)))/1000)));return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toString().padStart(2,'0')}`});
const discovered=computed(()=>room.value?.clues.filter(c=>c.body)||[]),selectedClue=computed(()=>room.value?.clues.find(c=>c.id===selected.value));
const relatedMessages=computed(()=>room.value?.messages.filter(m=>m.clueId===selected.value)||[]);
const inventoryNames={'loan-register':'借衣登记副本','coat-observation':'外套破口观察','fabric-observation':'门钉布片观察','chen-comparison':'陈伯的核实方向','comparison-note':'H01 布片对照记录'};
const currentPortrait=computed(()=>`/assets/portraits/${appearance.value}.webp`);
function portrait(p,small=true){return `/assets/portraits/${p?.avatarId|| (p?.role?`${p.role}-1`:'chen')}${small?'-thumb':''}.webp`}
function who(id){return room.value?.players.find(p=>p.id===id)}
function speakerName(id){return who(id)?.name||({'npc:chen':'陈伯','npc:diary':'日记回响'}[id])||'队友'}
function roleName(id){return config.value.roles.find(r=>r.id===id)?.name||'尚未选角'}
function keep(){try{localStorage.setItem('echo.formal.session',JSON.stringify(session))}catch{error.value='当前浏览器无法保存重连凭据，请勿关闭页面。'}}
async function api(path,body,auth=true){const res=await fetch(path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(auth&&session.token?{'Authorization':`Bearer ${session.token}`}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await res.json();if(!res.ok)throw Error(data.error||'暂时无法完成操作。');return data}
function receive(data){if(data.state){room.value={...data.state,receivedAt:Date.now()};waiting.value=null;session.code=data.state.code;session.queued=false;keep()}else if(data.waiting){waiting.value=data.waiting;session.queued=true;keep()}else if(data.expired){waiting.value=null;session.queued=false;keep();notice.value=data.message||'排队已结束，可以重新加入。'}online.value=true}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function enter(){await run(async()=>{const result=await api(`/api/${mode.value==='friends'?'create':mode.value==='join'?'join':mode.value==='quick'?'match':'solo'}`,{name:name.value,role:role.value,avatarId:appearance.value,code:code.value.toUpperCase()},false);session={token:result.token,queued:mode.value==='quick'};keep();receive(result.match||result)})}
async function action(type,body={}){const payload={phase:room.value.phase,...body},key=JSON.stringify([room.value.code,type,payload]);if(lastRequest?.key!==key)lastRequest={key,id:crypto.randomUUID()};const data=await api(`/api/room/${room.value.code}/${type}`,{...payload,requestId:lastRequest.id});lastRequest=null;receive(data);return data.outcome}
async function pollState(){if(destroyed)return;try{if(session.queued)receive(await api('/api/match'));else if(session.code&&session.token)receive({state:await api(`/api/room/${session.code}/state`)});}catch(e){online.value=false;error.value=`连接中断：${e.message} 将自动重连。`}finally{if(!destroyed)poll=setTimeout(pollState,room.value?.teammatePending?.length?500:1500)}}
async function cancel(){await run(async()=>{const data=await api('/api/match/cancel',{});if(data.state)receive(data);else{waiting.value=null;session={};keep();notice.value='已取消匹配，可以换角色或单人试玩。'}})}
async function leave(){if(!confirm('离开此页面不会暂停房间。确定返回首页？'))return;if(room.value?.phase===0){try{await api(`/api/room/${room.value.code}/leave`,{})}catch(e){error.value=e.message;return}}session={};keep();room.value=null;waiting.value=null;selected.value=null;error.value=''}
async function chooseRole(id){if(!room.value){role.value=id;appearance.value=`${id}-1`;return}await run(()=>action('seat',{role:id,avatarId:`${id}-1`}))}
async function changeAppearance(id){if(!room.value){appearance.value=id;return}await run(()=>action('seat',{role:me.value.role,avatarId:id}))}
async function invite(){const link=`${location.origin}/?room=${room.value.code}`;try{await navigator.clipboard.writeText(link);notice.value='邀请链接已复制，好友打开后会预填房间码。'}catch{notice.value=`邀请链接：${link}`}}
async function addBots(){const missing=config.value.roles.filter(r=>!room.value.players.some(p=>p.role===r.id)).map(r=>r.name).join('、');if(confirm(`由 AI 扮演${missing}，现在开始？`))await run(()=>action('add-bot'))}
function openClue(id){selected.value=id;detail.value=true} function scrollReply(id){document.getElementById(id)?.scrollIntoView({block:'center',behavior:'smooth'})} function quote(id,to=''){detail.value=false;selected.value=id;target.value=to;tab.value='discussion';text.value=`关于【${id}】，${room.value.clues.find(c=>c.id===id)?.question||'你怎样解释？'}`;nextTick(()=>document.querySelector('#discussion-text')?.focus())}
function respond(m){replyTo.value=m.id;target.value=who(m.speakerId)?.id||'';selected.value=m.clueId||null;tab.value='discussion';nextTick(()=>document.querySelector('#discussion-text')?.focus())}
function closeOnEscape(e){if(e.key==='Escape'){detail.value=false;selected.value=null}}
async function send(){await run(async()=>{await action('message',{text:text.value,to:target.value||undefined,clueId:selected.value||undefined,replyTo:replyTo.value||undefined});text.value='';replyTo.value=''})}
async function explore(type,target,itemId){await run(async()=>{const out=await action(type,{target,itemId});observation.value=out.text})}
function selectVote(id){voteTarget.value=id;voteClues.value=[]}
function toggleClue(id){if(voteClues.value.includes(id))voteClues.value=voteClues.value.filter(x=>x!==id);else if(voteClues.value.length<2)voteClues.value.push(id)}
async function submitVote(){if(confirm(`提交${voteTarget.value?`对 ${who(voteTarget.value)?.name} 的指认`:'弃票'}？提交后不可更改。`))await run(()=>action('vote',{target:voteTarget.value,clueIds:voteClues.value}))}
async function ask(npc){await run(()=>action('ask',{npc,text:text.value||'请解释这份原始记录。',clueId:selected.value||undefined}))}
watch(()=>room.value?.phase,(p,old)=>{selected.value=null;observation.value='';replyTo.value='';text.value='';tab.value=p===1?'role':p===4?'vote':p===5?'review':'scene';if(p===undefined){notice.value='';return}if(old!==undefined&&p!==old)notice.value=`已进入${names[p]}`});
onMounted(async()=>{document.addEventListener('keydown',closeOnEscape);try{config.value=await api('/api/bootstrap',undefined,false)}catch(e){error.value=e.message}if(code.value)mode.value='join';clockTimer=setInterval(()=>clock.value=Date.now(),500);pollState()});
onBeforeUnmount(()=>{destroyed=true;clearTimeout(poll);clearInterval(clockTimer);document.removeEventListener('keydown',closeOnEscape)});
</script>

<template>
 <div class="app-shell">
  <header class="masthead"><a href="/" @click.prevent="room?leave():null" class="brand">迷案<span>·</span>回声 <small>听雨轩</small></a><MusicPlayer :phase="room?.phase||0"/></header>
  <div class="toast error" v-if="error" role="alert">{{error}}<button @click="error=''" aria-label="关闭错误">×</button></div>
  <div class="toast" v-if="notice" role="status">{{notice}}<button @click="notice=''" aria-label="关闭提示">×</button></div>
  <main v-if="!room&&!waiting" class="entry">
   <section class="intro" data-enter><p class="eyebrow">一场雨停之后的密室命案</p><h1>门从里面锁上。<br>谁的话，<em>留下了破绽？</em></h1><p class="lede">听雨轩的主人死于书房。三个人，各自隐瞒着一段往事。走进宅邸，带着证物，问出你最在意的那句话。</p><div class="entry-facts"><span>三人共同推理</span><span>约 15–20 分钟</span><span>单人可带 AI</span></div><div class="case-seal">听雨轩<br><small>卷宗 · 壹</small></div></section>
   <section class="entry-form" aria-label="开始游戏"><div class="mode-tabs"><button v-for="[id,label] in [['solo','单人试玩'],['friends','好友开房'],['quick','快速匹配'],['join','凭码加入']]" :class="{active:mode===id}" @click="mode=id">{{label}}</button></div><label>你的昵称<input v-model="name" maxlength="20" autocomplete="nickname" placeholder="让同伴怎么称呼你" /></label><label v-if="mode==='join'">房间码<input v-model="code" maxlength="8" placeholder="8 位房间码" class="code-input" /></label><p class="field-label">选择你的角色</p><div class="role-choices"><button v-for="r in config.roles" :class="{active:role===r.id}" @click="chooseRole(r.id)"><img :src="`/assets/portraits/${r.id}-1-thumb.webp`" alt=""/><b>{{r.name}}</b><small>{{r.title}}</small></button></div><div class="appearance-picker"><img :src="currentPortrait" :alt="roleName(role)+'所选外观'"/><div><p class="field-label">人物外观</p><button v-for="n in [1,2]" :aria-pressed="appearance===`${role}-${n}`" :class="{active:appearance===`${role}-${n}`}" @click="changeAppearance(`${role}-${n}`)">{{n===1?'正装':'日常'}}</button><p>开场后固定本局外观</p></div></div><button class="primary full" @click="enter" :disabled="busy||!name.trim()">{{busy?'正在进入…':mode==='solo'?'带两名 AI 进入故事':mode==='friends'?'创建好友房':mode==='quick'?'按所选角色寻找同伴':'加入好友房'}} <span>↗</span></button><p class="subtle">{{mode==='quick'?'仅匹配真人；三个不同角色凑齐后自动开始。':mode==='solo'?'读本后即可调查，所有必要证物均有固定获取路径。':'分享邀请链接；人数不足时可由房主补充 AI。'}}</p></section>
  </main>
  <main v-else-if="waiting" class="waiting panel"><p class="eyebrow">正在寻找另外两种角色</p><img :src="`/assets/portraits/${waiting.avatarId}.webp`" alt="所选外观"/><h1>{{roleName(waiting.role)}}，等你入场</h1><p>已等待 {{Math.max(0,Math.floor((clock-waiting.since)/1000))}} 秒。匹配成功后自动进入读本。</p><button class="primary" @click="cancel" :disabled="busy">取消匹配</button><p class="subtle">取消后可换角色，或返回单人试玩。</p></main>
  <template v-else>
   <section class="phase-banner" aria-live="polite"><div><p class="eyebrow">房间 {{room.code}} · {{room.mode==='solo'?'单人试玩':room.mode==='quick'?'真人匹配':'好友房'}}</p><h1>{{names[room.phase]}}<span v-if="room.phase>0&&room.phase<5" class="countdown">{{remaining}}</span></h1><p>{{goals[room.phase]}}</p></div><div class="phase-check" v-if="room.phase>=1&&room.phase<=3"><p>真人确认 {{room.phaseReady.length}} / {{room.players.filter(p=>!p.isAI).length}}</p><button :disabled="busy||room.phaseReady.includes(room.me)" class="primary" @click="run(()=>action('phase-ready'))">{{room.phaseReady.includes(room.me)?'已确认，等待同伴':room.phase===1?'我读完了':'我已完成本阶段'}}</button><small>{{room.phaseBlock||'全体真人确认后自动推进'}}</small></div><span v-if="!online" class="offline">正在重新连接…</span></section>
   <div class="members"><div v-for="p in room.players" :key="p.id" class="member"><img v-if="p.role" :src="portrait(p)" alt=""/><div><b>{{p.name}} <small v-if="p.id===room.me">我</small><small v-if="p.isAI">AI</small></b><span>{{roleName(p.role)}} · {{room.phase===0?(p.isReady?'已准备':'未准备'):(p.online?'在场':'暂离')}}</span></div></div><button v-if="room.phase===0" @click="invite">复制邀请</button></div>
   <main v-if="room.phase===0" class="lobby panel"><h2>选择角色，等同伴落座</h2><p>房间码 <strong class="room-code">{{room.code}}</strong></p><div class="role-choices"><button v-for="r in config.roles" :disabled="busy||room.players.some(p=>p.id!==room.me&&p.role===r.id)" :class="{active:me.role===r.id}" @click="chooseRole(r.id)"><img :src="`/assets/portraits/${r.id}-1-thumb.webp`" alt=""/><b>{{r.name}}</b><small>{{r.intro}}</small></button></div><div v-if="me.role" class="appearance-options"><button v-for="n in [1,2]" :class="{active:me.avatarId===`${me.role}-${n}`}" @click="changeAppearance(`${me.role}-${n}`)"><img :src="`/assets/portraits/${me.role}-${n}-thumb.webp`" alt=""/>{{n===1?'正装':'日常'}}</button></div><button class="primary" :disabled="!me.role||busy" @click="run(()=>action('ready',{ready:!me.isReady}))">{{me.isReady?'取消准备':'准备好了'}}</button><template v-if="room.host"><button :disabled="busy||room.players.length!==3||!room.players.every(p=>p.isReady)" @click="run(()=>action('start'))">三人开场</button><button :disabled="busy||!room.canAddBots" @click="addBots">添加 AI 并开始</button><button :disabled="busy||!room.canAddBots||room.players.length!==2" @click="run(()=>action(room.recruiting?'cancel-recruit':'recruit'))">{{room.recruiting?'取消招募':'招募一位真人'}}</button></template><p v-if="room.recruiting" role="status">正在为缺少的角色招募真人；取消准备或有好友加入时停止招募。</p></main>
   <template v-else>
    <nav class="game-tabs" aria-label="游戏视图"><button v-for="[id,label] in [['scene','宅邸调查'],['evidence','证据板'],['discussion','讨论'],['role','我的角色'],...(room.phase===4?[['vote','指认']]:room.phase===5?[['review','复盘']]:[]) ]" :class="{active:tab===id}" @click="tab=id">{{label}}<small v-if="id==='evidence'">{{discovered.length}}/12</small></button></nav>
    <main class="game-main">
     <section v-if="tab==='role'" class="role-card panel"><div><p class="eyebrow">仅你可见 · 调查时随时回看</p><h2>{{roleName(me.role)}}</h2><dl class="brief"><template v-for="(line,i) in room.brief"><dt>{{['我是谁','我知道什么','我想隐瞒什么','我最想问谁'][i]}}</dt><dd>{{line}}</dd></template></dl><details><summary>展开完整身世与私人目标</summary><p class="prewrap">{{room.card}}</p></details></div><img :src="portrait(me,false)" alt="角色半身立绘"/></section>
     <section v-if="tab==='scene'" class="investigation">
      <template v-if="room.phase===1"><div class="panel"><h2>先读一读你的故事</h2><p>你的身份、见闻与秘密只对本人显示。读完后点击顶部确认。</p><button class="primary" @click="tab='role'">查看我的角色</button></div></template>
      <template v-else-if="room.phase===2||room.phase>=3">
       <div v-if="room.phase>=3" class="scene-navigation"><button v-for="[id,label] in [['account','账房'],['hall','后院廊下'],['bedroom','卧室搜查'],['courtyard','暖阁门钉']]" :class="{active:scene===id}" @click="scene=id">{{label}}</button><label><input type="checkbox" v-model="hint"/> 显示调查点</label></div>
       <div class="scene-art" :class="[scene,{hints:hint,'scene-file':room.phase===2}]" role="group" :aria-label="scene==='account'?'听雨轩账房调查场景':'听雨轩'+scene+'调查场景'"><div class="scene-caption"><span>听雨轩</span><b>{{room.phase===2?'现场封存卷宗':room.scenes?.find(s=>s.id===scene)?.title}}</b></div><template v-if="room.phase===2"><button class="hotspot ledger" @click="run(()=>action('clue',{clueId:'C01'}))">书房门锁</button><button class="hotspot object" @click="run(()=>action('clue',{clueId:'C02'}))">书桌镇纸</button><button class="hotspot npc" @click="run(()=>action('clue',{clueId:'C03'}))">检验报告</button><button class="hotspot fourth" @click="run(()=>action('clue',{clueId:'C04'}))">遗嘱草稿</button></template><template v-else-if="room.phase===3"><button v-if="scene==='account'" class="hotspot ledger" @click="explore('inspect','register')">检查登记册</button><button v-if="scene==='hall'" class="hotspot npc" @click="explore('inspect','chen')"><img src="/assets/portraits/chen-thumb.webp" alt=""/>与陈伯交谈</button><button v-if="scene==='bedroom'" class="hotspot object" @click="explore('inspect','coat')">检查蓝外套</button><button v-if="scene==='courtyard'" class="hotspot object" @click="explore('inspect','cloth')">检查封存布片</button></template><p v-else class="scene-ended">调查已结束，可回顾下方探索记录。</p></div>
       <div class="observation panel" v-if="observation" role="status"><p class="eyebrow">本次观察</p><p>{{observation}}</p><button @click="tab='evidence'">查看证据板 ↗</button></div>
       <div class="inventory panel"><div class="section-heading"><h2>共享背包</h2><span>{{room.inventory.length}} 项</span></div><p v-if="!room.inventory.length" class="subtle">点击场景中的物品，取得调查记录。</p><div class="inventory-list"><span v-for="item in room.inventory">{{inventoryNames[item]||item}}</span></div><template v-if="room.phase===3"><button :disabled="busy||!room.inventory.includes('loan-register')" @click="explore('present','chen','loan-register')">向陈伯出示借衣登记</button><button :disabled="busy||!['chen-comparison','coat-observation','fabric-observation'].every(i=>room.inventory.includes(i))" @click="explore('compare','coat-fabric')">对照外套与布片</button></template><p class="subtle">登记 → 陈伯核实 → 分别检查外套与布片 → 对照。共享进度，重复操作不会重复发奖。</p></div>
       <details class="panel"><summary>本局探索记录（{{room.exploration.length}}）</summary><p v-for="e in room.exploration" class="exploration-record"><b>{{who(e.by)?.name}}</b> · {{e.text}}</p></details>
      </template>
     </section>
     <section v-if="tab==='evidence'" class="evidence-view"><div class="section-heading"><div><p class="eyebrow">公开事实，共同核对</p><h2>共享证据板</h2></div><span>{{discovered.length}} / 12 已公开</span></div><div class="evidence-grid"><article v-for="c in room.clues" :key="c.id" class="clue" :class="{locked:!c.body}"><div class="clue-title"><span>{{c.id}}</span><small>{{c.via||'尚未取得'}}</small></div><h3>{{c.title}}</h3><p v-if="c.body">{{c.body}}</p><p v-else>调查此处，取得可供所有人核对的原始记录。</p><button v-if="!c.body&&room.phase<=3" :disabled="busy" @click="run(()=>action('clue',{clueId:c.id}))">调查取证</button><template v-else-if="c.body"><button @click="openClue(c.id)">查看关联讨论</button><button v-if="room.phase===2||room.phase===3" class="text-button" @click="quote(c.id)">引用追问 ↗</button></template></article></div></section>
     <section v-if="tab==='discussion'" class="discussion panel"><div class="section-heading"><h2>当面对质</h2><span>公开讨论 · 按身份标注</span></div><div class="chat-log" aria-live="polite"><p v-if="!room.messages.length" class="subtle">从证据板引用一件证物，问问同伴如何解释。</p><article v-for="m in room.messages" :key="m.id" class="message"><div v-if="m.speakerId==='npc:diary'" class="diary-avatar" aria-label="生前日记">记</div><img v-else :src="who(m.speakerId)?portrait(who(m.speakerId)):'/assets/portraits/chen-thumb.webp'" alt=""/><div><header><b>{{m.by}}</b><small v-if="who(m.speakerId)?.isAI">AI 队友</small><small v-if="who(m.speakerId)">{{roleName(who(m.speakerId).role)}}</small><span v-if="m.to">→ {{speakerName(m.to)}}</span></header><button v-if="m.replyTo" class="reply-reference" @click="scrollReply(m.replyTo)">回应上一条提问</button><p :id="m.id">{{m.text}}</p><button v-if="m.clueId" class="citation" @click="openClue(m.clueId)">{{m.clueId}} · 返回证物 ↗</button><button v-if="room.phase<4&&who(m.speakerId)&&m.speakerId!==room.me" class="text-button" @click="respond(m)">追问</button></div></article></div><p v-for="job in room.teammatePending" role="status" class="subtle">{{who(job.botId)?.name}} 正在回应…</p><form v-if="room.phase===2||room.phase===3" class="composer" @submit.prevent="send"><label>对话对象<select v-model="target"><option value="">所有人（普通发言）</option><option v-for="p in room.players.filter(p=>p.id!==room.me)" :value="p.id">{{p.name}} · {{roleName(p.role)}}{{p.isAI?'（AI）':''}}</option></select></label><p v-if="replyTo" class="subtle">正在回应一条发言 <button type="button" @click="replyTo=''">取消</button></p><div v-if="selectedClue" class="quoted">引用 {{selectedClue.id}} · {{selectedClue.title}} <button type="button" @click="selected=null">×</button></div><textarea id="discussion-text" v-model="text" maxlength="300" rows="3" placeholder="你看见了什么？又怎样解释？"/><div class="composer-actions"><span class="subtle">点名 AI 才会回应 · 剩余 {{room.aiRemaining}} 次</span><button class="primary" :disabled="busy||!text.trim()">{{busy?'正在回应…':'发送'}}</button></div><div class="npc-actions"><button type="button" @click="ask('chen')" :disabled="busy||!discovered.some(c=>c.id==='C06')">带记录问陈伯</button><button type="button" @click="ask('diary')" :disabled="busy||!discovered.some(c=>c.id==='C12')">查阅日记回响</button></div></form></section>
     <section v-if="tab==='vote'&&room.phase===4" class="vote-panel panel"><p class="eyebrow">本人的指认与依据，结算前保密</p><h2>{{room.voted?'你的判断已封存':'这一票，你依据什么？'}}</h2><p>已提交 {{room.votedCount}} / 3；超时未投计弃票。</p><template v-if="!room.voted"><div class="vote-choices"><button v-for="p in room.players.filter(p=>p.id!==room.me)" :class="{active:voteTarget===p.id}" @click="selectVote(p.id)"><img :src="portrait(p,false)" alt=""/><b>{{p.name}}</b><span>{{roleName(p.role)}}{{p.isAI?' · AI':''}}</span></button><button :class="{active:!voteTarget}" @click="selectVote('')">弃票<br><small>证据还不足以指认</small></button></div><template v-if="voteTarget"><h3>引用 1–2 件证物</h3><div class="vote-clues"><label v-for="c in discovered"><input type="checkbox" :checked="voteClues.includes(c.id)" @change="toggleClue(c.id)" :disabled="voteClues.length===2&&!voteClues.includes(c.id)"/>{{c.id}} {{c.title}}</label></div></template><button class="primary" :disabled="busy||(!!voteTarget&&!voteClues.length)" @click="submitVote">封存我的判断</button></template></section>
     <section v-if="tab==='review'&&room.result" class="review"><div class="panel personal"><p class="eyebrow">先看你自己的推理</p><h2>你选择了 {{room.result.myChoice}}</h2><p v-if="!room.result.myClueIds.length">你没有引用证物。再看看哪些公开事实可以互相印证。</p><article v-for="id in room.result.myClueIds"><button @click="openClue(id)">{{id}} · {{room.clues.find(c=>c.id===id)?.title}} ↗</button><p>{{room.clues.find(c=>c.id===id)?.meaning}}</p></article></div><div class="panel"><p class="eyebrow">三席共同结局</p><h2>{{room.result.label}}</h2><div class="result-votes"><p v-for="v in room.result.votes"><b>{{who(v.from)?.name}} · {{roleName(who(v.from)?.role)}}</b> → {{who(v.target)?.name||'弃票'}} <span>{{v.clueIds.join('、')}}</span></p></div></div><div class="panel"><h2>把证据连成一条线</h2><div v-for="[title,ids] in [['死因与凶器',['C02','C03']],['密室与进入路线',['C01','C05','C07','C08']],['人物身份与时间',['C06','C09','C10','C11']]]" class="evidence-chain"><h3>{{title}}</h3><button v-for="id in ids" @click="openClue(id)">{{id}} · {{room.clues.find(c=>c.id===id)?.via}}</button><p v-for="id in ids">{{room.clues.find(c=>c.id===id)?.meaning}}</p></div></div><details class="panel"><summary>完整时间线与三人的隐瞒</summary><p v-for="t in room.result.timeline"><b>{{t.time}}</b> {{t.event}}</p><p v-for="s in room.result.secrets"><b>{{s.name}}</b> {{s.secret}}</p></details><div class="panel"><h2>回顾探索过程</h2><p v-for="e in room.exploration">{{who(e.by)?.name}}：{{e.text}}</p><p v-if="!room.events.includes('coat-fabric')">本局尚未完成 H01 对照。它是【C10】的进一步理解：相合破口只能支持物品来源，还需【C11】的时间范围与【C06】的见闻。</p><button @click="tab='scene'">返回原场景回顾</button><button @click="leave">返回首页</button></div></section>
    </main>
   </template>
  </template>
  <footer><span>迷案·回声 · 听雨轩</span><a v-if="config.icp" href="https://beian.miit.gov.cn/" target="_blank" rel="noopener">{{config.icp}}</a><a v-if="config.police&&config.policeUrl" :href="config.policeUrl" target="_blank" rel="noopener">{{config.police}}</a><a href="/assets/manifest.json" target="_blank">素材与许可</a></footer>
  <div v-if="selectedClue?.body&&detail" class="modal-backdrop" @click.self="selected=null"><section class="evidence-detail panel" role="dialog" aria-modal="true" aria-label="证物详情"><button class="close" @click="selected=null" aria-label="关闭证物">×</button><p class="eyebrow">{{selectedClue.id}} · {{selectedClue.via}}</p><h2>{{selectedClue.title}}</h2><p>{{selectedClue.body}}</p><p class="question">尚待解释：{{selectedClue.question}}</p><p v-if="room.phase===5">能证明什么：{{selectedClue.meaning}} <button @click="openClue(selectedClue.related)">交叉验证 {{selectedClue.related}}</button></p><template v-if="room.phase===2||room.phase===3"><button class="primary" @click="quote(selectedClue.id)">引用到讨论</button><button v-for="p in room.players.filter(p=>p.id!==room.me)" @click="quote(selectedClue.id,p.id)">问 {{p.name}} · {{roleName(p.role)}}</button></template><h3>关联讨论</h3><p v-if="!relatedMessages.length" class="subtle">还没有人围绕这件证物发言。</p><article v-for="m in relatedMessages"><b>{{m.by}}</b><p>{{m.text}}</p></article></section></div>
 </div>
</template>
